const tracks=[['ko','한국어'],['vi','Tiếng Việt'],['zh','中文'],['ja','日本語']];
export function guideHeading(lang){return (copy[lang]||copy.ko)[0];}
export function guideVideos(lang){
 const c=copy[lang]||copy.ko;
 // The video is served from the user's public GitHub Pages site so both books
 // use one copy; subtitles remain local to each book.
 const origin=['localhost','127.0.0.1'].includes(globalThis.location?.hostname)?'':'https://isaacweb007.github.io/modu-ai/';
 const media=origin+'assets/guide-videos/guest-guide-v6.mp4';
 const selected=tracks.some(([code])=>code===lang)?lang:'ko';
 return `<section class="guide-videos" id="guide-videos" aria-labelledby="guide-videos-heading"><div class="guide-videos-header"><p>one shop · Rami</p><h3 id="guide-videos-heading">${esc(c[0])}</h3></div><div class="guide-videos-grid"><article class="guide-video-card"><div class="guide-video-copy"><h4>${esc(c[1])}</h4><p>${esc(c[2])}</p></div><video controls playsinline preload="none" crossorigin="anonymous" poster="assets/guide-videos/guest-poster.jpg" aria-label="${esc(c[1])}"><source src="${media}" type="video/mp4">${tracks.map(([code,label])=>`<track kind="subtitles" src="assets/guide-videos/${code}.vtt" srclang="${code}" label="${label}" ${code===selected?'default':''}>`).join('')}</video><p class="guide-video-meta">${esc(c[3])}</p><p class="guide-video-note">${esc(c[4])}</p></article><article class="guide-video-card guide-video-owner"><div class="guide-video-copy"><h4>${esc(c[5])}</h4><p>${esc(ownerDescription[lang]||ownerDescription.ko)}</p></div><video controls playsinline preload="none" crossorigin="anonymous" poster="assets/guide-videos/owner-poster.jpg" aria-label="${esc(c[5])}"><source src="${origin}assets/guide-videos/owner-guide-v2.mp4" type="video/mp4">${tracks.map(([code,label])=>`<track kind="subtitles" src="assets/guide-videos/owner-${code}.vtt?v=5.39.0" srclang="${code}" label="${label}" ${code===selected?'default':''}>`).join('')}</video><p class="guide-video-meta">${esc(c[3])}</p><p class="guide-video-note">${esc(ownerNote[lang]||ownerNote.ko)}</p></article></div></section>`;
}
